   =================================================================== */

#include <Arduino.h>

#define SENSOR_PIN 34
#define RELAY_PIN 23
#define STATUS_LED 2
#define BUZZER_PIN 19

float sensorValue = 0.0;
bool relayState = false;
unsigned long lastTelemetryTime = 0;
const unsigned long telemetryInterval = 2000;

void setup() {
  Serial.begin(115200);
  pinMode(SENSOR_PIN, INPUT);
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(STATUS_LED, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);

  digitalWrite(RELAY_PIN, LOW);
  digitalWrite(STATUS_LED, HIGH);
  Serial.println("[SYSTEM INIT] LPG Gas Leakage Detector with MQ-6 & GSM SMS Alert Firmware Booted Successfully.");
}

void loop() {
  unsigned long now = millis();
  if (now - lastTelemetryTime >= telemetryInterval) {
    lastTelemetryTime = now;

    // Read analog transducer value
    int raw = analogRead(SENSOR_PIN);
    sensorValue = (raw / 4095.0) * 100.0; // Scaled percentage

    // Safety Threshold Logic
    if (sensorValue > 75.0) {
      relayState = true;
      digitalWrite(RELAY_PIN, HIGH);
      digitalWrite(BUZZER_PIN, HIGH);
