      relayState = false;
      digitalWrite(RELAY_PIN, LOW);
      digitalWrite(BUZZER_PIN, LOW);
      Serial.printf("[TELEMETRY] Sensor: %.2f%% | Relay: OFF\n", sensorValue);
    }
  }
}

document.addEventListener("DOMContentLoaded", () => {
