  unsigned long now = millis();
  if (now - lastTelemetryTime >= telemetryInterval) {
    lastTelemetryTime = now;

    // Read analog transducer value
    int raw = analogRead(SENSOR_PIN);
    sensorValue = (raw / 4095.0) * 100.0; // Scaled percentage

