    engine.displayRecords();
    engine.addRecord(104, "Delta Real-Time Execution", 99.3);
    engine.displayRecords();
    engine.exportToDisk();

    std::cout << "[SYSTEM FINISHED] Execution complete with exit code 0.\n";
    return 0;
}

