   Domain: Web & Full Stack | Academic Year: 2nd Year Project
   =================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

:root {
  --theme-primary: #6366f1;
  --theme-secondary: #818cf8;
  --theme-glow: rgba(99, 102, 241, 0.25);
  --bg-main: #0a0e1a;
  --bg-card: rgba(17, 24, 39, 0.85);
  --border-color: rgba(255, 255, 255, 0.1);
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  background-color: var(--bg-main);
  color: var(--text-main);
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem;
}

.container {
  max-width: 1000px;
  margin: 0 auto;
}

header {
  text-align: center;
  margin-bottom: 2rem;
}

header h1, header h2 {
  font-size: 2rem;
  color: #ffffff;
  margin-bottom: 0.5rem;
}

.badge {
  display: inline-block;
  background: var(--theme-glow);
  color: var(--theme-secondary);
  border: 1px solid var(--theme-primary);
  padding: 0.35rem 0.85rem;
  border-radius: 9999px;
  font-size: 0.8rem;
  font-weight: 600;
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 2rem;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  margin-bottom: 1.5rem;
}

.form-group {
  margin-bottom: 1.25rem;
  display: flex;
  gap: 0.75rem;
}

input, select, textarea {
  flex: 1;
  background: #1e293b;
  border: 1px solid var(--border-color);
  color: #fff;
  padding: 0.75rem 1rem;
  border-radius: 8px;
  font-size: 0.95rem;
  font-family: inherit;
}

input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: var(--theme-primary);
  box-shadow: 0 0 10px var(--theme-glow);
}

.btn {
  background: linear-gradient(135deg, var(--theme-primary), var(--theme-secondary));
  color: #fff;
  border: none;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 15px var(--theme-glow);
}

.output-box {
  background: #0f172a;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 1.25rem;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.9rem;
  min-height: 80px;
  color: #38bdf8;
  white-space: pre-wrap;
  word-break: break-all;
}

// ===================================================================
// Weather Analytics Dashboard with Chart.js Forecasts - Express.js REST API Server
// ===================================================================
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

let items = [
  { id: 1, title: "Standard Package / Core Service", price: 49.99, inStock: true },
  { id: 2, title: "Enterprise Tier / Cloud Module", price: 149.99, inStock: true },
  { id: 3, title: "Custom Integration Extension", price: 89.99, inStock: true }
];

app.get('/api/items', (req, res) => {
  res.json({ project: "Weather Analytics Dashboard with Chart.js Forecasts", items, count: items.length });
});

app.post('/api/items', (req, res) => {
  const { title, price } = req.body;
  if (!title || !price) return res.status(400).json({ error: "Title and price required" });
  const newItem = { id: items.length + 1, title, price: parseFloat(price), inStock: true };
  items.push(newItem);
  res.status(201).json(newItem);
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => console.log(`[SERVER] Weather Analytics Dashboard with Chart.js Forecasts running on port ${PORT}`));

document.addEventListener("DOMContentLoaded", () => {
  const itemTitle = document.getElementById("itemTitle");
  const itemPrice = document.getElementById("itemPrice");
  const addItemBtn = document.getElementById("addItemBtn");
  const itemList = document.getElementById("itemList");

  let items = [
    { id: 1, title: "Standard Package / Core Service", price: 49.99 },
    { id: 2, title: "Enterprise Tier / Cloud Module", price: 149.99 }
  ];

  function render() {
    itemList.innerHTML = "";
    items.forEach(it => {
      const div = document.createElement("div");
      div.style.cssText = "display: flex; justify-content: space-between; background: #1e293b; padding: 1rem; border-radius: 8px;";
      div.innerHTML = `<span><strong>${it.title}</strong></span><span style="color: #38bdf8; font-weight: 700;">$${it.price.toFixed(2)}</span>`;
      itemList.appendChild(div);
    });
  }

  addItemBtn.addEventListener("click", () => {
    const title = itemTitle.value.trim();
    const price = parseFloat(itemPrice.value);
    if (!title || isNaN(price)) return alert("Please enter valid item details.");
    items.push({ id: items.length + 1, title, price });
    itemTitle.value = "";
    itemPrice.value = "";
    render();
  });

  render();
});

{
  "name": "fullstack-project",
  "version": "1.0.0",
  "main": "backend/server.js",
  "scripts": {
    "start": "node backend/server.js"
  },
  "dependencies": {
    "express": "^4.18.2",
    "cors": "^2.8.5"
  }
}

