   Domain: Java & Enterprise | Academic Year: 1st Year Project
   =================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

:root {
  --theme-primary: #ea580c;
  --theme-secondary: #fb923c;
  --theme-glow: rgba(234, 88, 12, 0.25);
  --bg-main: #0a0e1a;
  --bg-card: rgba(17, 24, 39, 0.85);
  --border-color: rgba(255, 255, 255, 0.1);
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  background-color: var(--bg-main);
  color: var(--text-main);
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem;
}

.container {
  max-width: 1000px;
  margin: 0 auto;
}

header {
  text-align: center;
  margin-bottom: 2rem;
}

header h1, header h2 {
  font-size: 2rem;
  color: #ffffff;
  margin-bottom: 0.5rem;
}

.badge {
  display: inline-block;
  background: var(--theme-glow);
  color: var(--theme-secondary);
  border: 1px solid var(--theme-primary);
  padding: 0.35rem 0.85rem;
  border-radius: 9999px;
  font-size: 0.8rem;
  font-weight: 600;
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 2rem;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  margin-bottom: 1.5rem;
}

.form-group {
  margin-bottom: 1.25rem;
  display: flex;
  gap: 0.75rem;
}

input, select, textarea {
  flex: 1;
  background: #1e293b;
  border: 1px solid var(--border-color);
  color: #fff;
  padding: 0.75rem 1rem;
  border-radius: 8px;
  font-size: 0.95rem;
  font-family: inherit;
}

input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: var(--theme-primary);
  box-shadow: 0 0 10px var(--theme-glow);
}

.btn {
  background: linear-gradient(135deg, var(--theme-primary), var(--theme-secondary));
  color: #fff;
  border: none;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 15px var(--theme-glow);
}

.output-box {
  background: #0f172a;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 1.25rem;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.9rem;
  min-height: 80px;
  color: #38bdf8;
  white-space: pre-wrap;
  word-break: break-all;
}

package com.projectforge.controller;

import org.springframework.web.bind.annotation.*;
import java.util.*;

@RestController
@RequestMapping("/api/v1/records")
@CrossOrigin(origins = "*")
public class ApiController {

    private final List<Map<String, Object>> records = new ArrayList<>();

    public ApiController() {
        Map<String, Object> r1 = new HashMap<>();
        r1.put("id", 101L);
        r1.put("name", "Enterprise Accounting & Ledger Module");
        r1.put("status", "ACTIVE");
        records.add(r1);
    }

    @GetMapping
    public List<Map<String, Object>> getAllRecords() {
        return records;
    }

    @PostMapping
    public Map<String, Object> createRecord(@RequestBody Map<String, Object> payload) {
        payload.put("id", System.currentTimeMillis());
        payload.put("status", "PROCESSED");
        records.add(payload);
        return payload;
    }
}

document.addEventListener("DOMContentLoaded", () => {
  const recordName = document.getElementById("recordName");
  const addRecordBtn = document.getElementById("addRecordBtn");
  const recordTable = document.getElementById("recordTable");

  let records = [
    { id: 101, name: "Enterprise Accounting & Ledger Module", status: "ACTIVE" },
    { id: 102, name: "Department Payroll Batch Runner", status: "VERIFIED" }
  ];

  function render() {
    let text = "ID       RECORD NAME                               STATUS\n";
    text += "--------------------------------------------------------\n";
    records.forEach(r => {
      text += `${String(r.id).padEnd(9)}${r.name.padEnd(42)}${r.status}\n`;
    });
    recordTable.innerText = text;
  }

  addRecordBtn.addEventListener("click", () => {
    const name = recordName.value.trim();
    if (!name) return alert("Enter record name");
    records.push({ id: 100 + records.length + 1, name, status: "PROCESSED" });
    recordName.value = "";
    render();
  });

  render();
});

