void main() => runApp(const MobileProjectApp());

class MobileProjectApp extends StatelessWidget {
  const MobileProjectApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: "TeleHealth: Doctor Appointment & Video Consultation App",
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorScheme: ColorScheme.fromSeed(seedColor: Colors.pink, brightness: Brightness.dark),
        useMaterial3: true,
      ),
      home: const HomeScreen(),
    );
  }
}

class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  int _counter = 0;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text("TeleHealth: Doctor Appointment & Video Consultation App")),
      body: Center(
        child: Column(
