  --theme-secondary: #f87171;
  --theme-glow: rgba(239, 68, 68, 0.25);
  --bg-main: #0a0e1a;
  --bg-card: rgba(17, 24, 39, 0.85);
  --border-color: rgba(255, 255, 255, 0.1);
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  background-color: var(--bg-main);
  color: var(--text-main);
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem;
}

.container {
  max-width: 1000px;
  margin: 0 auto;
}

header {
  text-align: center;
  margin-bottom: 2rem;
}

header h1, header h2 {
  font-size: 2rem;
  color: #ffffff;
  margin-bottom: 0.5rem;
}

.badge {
  display: inline-block;
  background: var(--theme-glow);
  color: var(--theme-secondary);
  border: 1px solid var(--theme-primary);
  padding: 0.35rem 0.85rem;
  border-radius: 9999px;
  font-size: 0.8rem;
  font-weight: 600;
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 2rem;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  margin-bottom: 1.5rem;
}

.form-group {
  margin-bottom: 1.25rem;
  display: flex;
  gap: 0.75rem;
}

input, select, textarea {
  flex: 1;
  background: #1e293b;
  border: 1px solid var(--border-color);
  color: #fff;
  padding: 0.75rem 1rem;
  border-radius: 8px;
  font-size: 0.95rem;
  font-family: inherit;
}

input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: var(--theme-primary);
  box-shadow: 0 0 10px var(--theme-glow);
}

.btn {
  background: linear-gradient(135deg, var(--theme-primary), var(--theme-secondary));
  color: #fff;
  border: none;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 15px var(--theme-glow);
}

.output-box {
  background: #0f172a;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 1.25rem;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.9rem;
  min-height: 80px;
  color: #38bdf8;
  white-space: pre-wrap;
  word-break: break-all;
}

document.addEventListener("DOMContentLoaded", () => {
  const targetIp = document.getElementById("targetIp");
  const scanBtn = document.getElementById("scanBtn");
  const securityConsole = document.getElementById("securityConsole");

  scanBtn.addEventListener("click", () => {
    const target = targetIp.value.trim() || "192.168.1.104";
    securityConsole.innerText = `[SCANNING] Probing target ${target} across TCP/UDP ports...`;

    setTimeout(() => {
      securityConsole.innerText = 
`=============================================================
